using System.Security.Claims; using DateMap.Application; using DateMap.Domain; using DateMap.Infrastructure; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace DateMap.Api.Controllers;
[ApiController,Authorize,Route("api/likes")] public sealed class LikesController(DateMapDbContext db):ControllerBase
{ [HttpPost("{targetId:guid}")] public async Task<ActionResult<LikeResult>> Like(Guid targetId){var source=Guid.Parse(User.FindFirstValue("profile_id")!);if(!await db.Profiles.AnyAsync(x=>x.Id==targetId&&x.IsActive))return NotFound();if(source==targetId)return UnprocessableEntity(new ProblemDetails{Title="A profile cannot like itself."});if(await db.Likes.AnyAsync(x=>x.SourceProfileId==source&&x.TargetProfileId==targetId))return Conflict(new ProblemDetails{Title="Like already exists."});db.Likes.Add(new(source,targetId));Guid? matchId=null;var created=false;if(await db.Likes.AnyAsync(x=>x.SourceProfileId==targetId&&x.TargetProfileId==source)){var pair=Match.Canonical(source,targetId);var match=await db.Matches.SingleOrDefaultAsync(x=>x.ProfileAId==pair.A&&x.ProfileBId==pair.B);if(match is null){match=new Match(source,targetId);db.Matches.Add(match);created=true;}matchId=match.Id;}await db.SaveChangesAsync();return Ok(new LikeResult(true,created,matchId));} }
